package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;
@Entity @Table(name="rsp_panel_rating_item") public class PanelRatingItem extends RspAuditedEntity{
 @Column(name="rating_id",nullable=false,length=36)private String ratingId;@Column(name="criterion_id",nullable=false,length=36)private String criterionId;@Column(name="raw_score",nullable=false,precision=12,scale=4)private BigDecimal rawScore;@Column(name="maximum_score",nullable=false,precision=12,scale=4)private BigDecimal maximumScore;@Column(name="normalized_score",nullable=false,precision=12,scale=4)private BigDecimal normalizedScore;@Column(name="weighted_score",nullable=false,precision=12,scale=4)private BigDecimal weightedScore;@Column(length=2000)private String remarks;
 protected PanelRatingItem(){}public PanelRatingItem(String agency,String rating,String criterion,BigDecimal raw,BigDecimal max,BigDecimal criterionWeight,int scale,RoundingMode rounding,String remarks){super(agency);ratingId=requiredText(rating,"ratingId");criterionId=requiredText(criterion,"criterionId");if(raw==null||max==null||raw.signum()<0||max.signum()<=0||raw.compareTo(max)>0)throw new IllegalArgumentException("Criterion score is outside bounds");rawScore=raw;maximumScore=max;normalizedScore=raw.multiply(new BigDecimal("100")).divide(max,scale,rounding);weightedScore=normalizedScore.multiply(criterionWeight).divide(new BigDecimal("100"),scale,rounding);this.remarks=optionalText(remarks);}
 public String getRatingId(){return ratingId;}public String getCriterionId(){return criterionId;}public BigDecimal getRawScore(){return rawScore;}public BigDecimal getMaximumScore(){return maximumScore;}public BigDecimal getNormalizedScore(){return normalizedScore;}public BigDecimal getWeightedScore(){return weightedScore;}public String getRemarks(){return remarks;}
}
